"""Synthetic raster fixtures strictly for automated software unit testing.

CRITICAL RESEARCH INTEGRITY RULE:
Artifacts generated by this fixture are labelled `SYNTHETIC_TEST_FIXTURE`.
They must NEVER be used to claim observed flood damages or cited as research evidence.
"""

from __future__ import annotations
from pathlib import Path
from typing import Tuple
import numpy as np
import rasterio
from rasterio.transform import from_origin


def create_synthetic_test_raster_pair(
    output_dir: Path,
    width: int = 50,
    height: int = 50,
    crs: str = "EPSG:4326",
    flood_delta_db: float = -6.0,
) -> Tuple[Path, Path]:
    """Generate minimal synthetic pre/post GeoTIFFs tagged explicitly as SYNTHETIC_TEST_FIXTURE.

    Used strictly to verify software array calculations and pipeline state progression.
    """
    output_dir = Path(output_dir)
    output_dir.mkdir(parents=True, exist_ok=True)

    transform = from_origin(85.1, 28.1, 0.001, 0.001)
    profile = {
        "driver": "GTiff",
        "height": height,
        "width": width,
        "count": 1,
        "dtype": rasterio.float32,
        "crs": crs,
        "transform": transform,
        "nodata": -9999.0,
    }

    pre_path = output_dir / "synthetic_fixture_pre.tif"
    post_path = output_dir / "synthetic_fixture_post.tif"

    arr_pre = np.full((height, width), -10.0, dtype=np.float32)
    arr_post = np.full((height, width), -10.0, dtype=np.float32)
    # Synthetic flood in top-left quadrant
    quad_h = max(2, height // 3)
    quad_w = max(2, width // 3)
    arr_post[0:quad_h, 0:quad_w] = -10.0 + flood_delta_db

    tags = {
        "DATA_ORIGIN": "SYNTHETIC_TEST_FIXTURE",
        "SAR_UNIT": "DECIBELS_DB",
        "SCIENTIFIC_VALIDITY": "TEST_ONLY_NOT_RESEARCH_EVIDENCE",
    }

    with rasterio.open(pre_path, "w", **profile) as dst:
        dst.write(arr_pre, 1)
        dst.update_tags(**tags)

    with rasterio.open(post_path, "w", **profile) as dst:
        dst.write(arr_post, 1)
        dst.update_tags(**tags)

    return pre_path, post_path
